import{_ as e,o as t,c as l,a2 as o}from"./chunks/framework.BjkiRu3Q.js";const u=JSON.parse('{"title":"Έλεγχος, έγκριση και δημοσίευση","description":"","frontmatter":{},"headers":[],"relativePath":"el/websites/publication-controls.md","filePath":"el/websites/publication-controls.md"}'),r={name:"el/websites/publication-controls.md"};function i(n,a,s,h,c,d){return t(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="ελεγχος-εγκριση-και-δημοσιευση" tabindex="-1">Έλεγχος, έγκριση και δημοσίευση <a class="header-anchor" href="#ελεγχος-εγκριση-και-δημοσιευση" aria-label="Permalink to &quot;Έλεγχος, έγκριση και δημοσίευση&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Έκδοση αναφοράς — προσχέδιο βάσει κώδικα</p><p>TransferBook+ v0.7.9. Η διαθεσιμότητα εξαρτάται από την εγκατεστημένη έκδοση, τα δικαιώματα και τις ρυθμίσεις. Ο οδηγός δεν επιβεβαιώνει δημόσια δημοσίευση.</p></div><h2 id="σκοπος" tabindex="-1">Σκοπός <a class="header-anchor" href="#σκοπος" aria-label="Permalink to &quot;Σκοπός&quot;">​</a></h2><p>Διαχωρίστε την ετοιμότητα σχεδιασμού από την επιχειρησιακή δημοσίευση. Ο οδηγός περιγράφει τη ροή του κώδικα αναφοράς, όχι άδεια δημοσίευσης.</p><h2 id="κυκλος-ελεγχου" tabindex="-1">Κύκλος ελέγχου <a class="header-anchor" href="#κυκλος-ελεγχου" aria-label="Permalink to &quot;Κύκλος ελέγχου&quot;">​</a></h2><ol><li>Ξεκινήστε με επικυρωμένο προσχέδιο εξουσιοδοτημένου καναλιού.</li><li>Ελέγξτε προεπισκόπηση, περιεχόμενο, γλώσσες, συσκευές και συμπεριφορά φόρμας.</li><li>Όπου υποστηρίζεται, χρησιμοποιήστε <strong>Mark Preview → Submit for Review → Approve Draft</strong>. Καταγράψτε σημείωση ελέγχου όπου χρειάζεται.</li><li>Σταματήστε στην έγκριση εκτός αν η δημοσίευση έχει ενεργοποιηθεί και εγκριθεί χωριστά. Ο κώδικας αναφοράς περιγράφει κλειδωμένα Publish και Connect Domain.</li></ol><h2 id="τι-δεν-κανει-η-εγκριση" tabindex="-1">Τι δεν κάνει η έγκριση <a class="header-anchor" href="#τι-δεν-κανει-η-εγκριση" aria-label="Permalink to &quot;Τι δεν κάνει η έγκριση&quot;">​</a></h2><p>Η έγκριση σχεδίου δεν αποδεικνύει δημόσια δρομολόγηση domain, SSL, πραγματικές κρατήσεις, πληρωμές ή εξερχόμενα μηνύματα. Απαιτούνται χωριστοί έλεγχοι. Η επαναφορά αναθεώρησης δημιουργεί νέο προσχέδιο και δεν αποτελεί αυτόματη δημόσια επαναφορά.</p><h2 id="αντιμετωπιση-προβληματων" tabindex="-1">Αντιμετώπιση προβλημάτων <a class="header-anchor" href="#αντιμετωπιση-προβληματων" aria-label="Permalink to &quot;Αντιμετώπιση προβλημάτων&quot;">​</a></h2><p>Αν η δημοσίευση είναι κλειδωμένη, μην παρακάμπτετε τον έλεγχο. Επιβεβαιώστε δικαιώματα και εγκεκριμένη πολιτική με τον υπεύθυνο διαχειριστή. Κρατήστε το προσχέδιο και εξαγόμενο αντίγραφο. Δείτε <a href="./template-manager.html">Template Manager</a>.</p><h2 id="περιορισμενη-φιλοξενια-και-διαχειριση-ιστοσελιδας-στη-v0-7-11" tabindex="-1">Περιορισμένη φιλοξενία και διαχείριση ιστοσελίδας στη v0.7.11 <a class="header-anchor" href="#περιορισμενη-φιλοξενια-και-διαχειριση-ιστοσελιδας-στη-v0-7-11" aria-label="Permalink to &quot;Περιορισμένη φιλοξενία και διαχείριση ιστοσελίδας στη v0.7.11&quot;">​</a></h2><p><strong>Κατάσταση: έκδοση staging ελεγμένη βάσει κώδικα, απενεργοποιημένη από προεπιλογή.</strong> Πρόκειται για χωριστή ροή Website Studio για καθορισμένο δοκιμαστικό προορισμό, όχι για τον γενικό κύκλο δημοσίευσης Template Manager παραπάνω. Απαιτούνται αντίστοιχη εγκατεστημένη έκδοση, χωριστά ενεργοποιημένες δυνατότητες, ο καθορισμένος διαχειριστής εταιρείας και δικαίωμα εγγραφής ιστοσελίδων. Το ανεξάρτητο kit δεν παρέχει λειτουργίες φιλοξενίας.</p><h3 id="ελεγχος-και-προετοιμασια-υποψηφιου" tabindex="-1">Έλεγχος και προετοιμασία υποψηφίου <a class="header-anchor" href="#ελεγχος-και-προετοιμασια-υποψηφιου" aria-label="Permalink to &quot;Έλεγχος και προετοιμασία υποψηφίου&quot;">​</a></h3><ol><li>Ελέγξτε κατάσταση φιλοξενίας και HTTPS από το εξουσιοδοτημένο πάνελ. Επιτυχής έλεγχος δεν επιτρέπει εγγραφή ούτε αποδεικνύει διαθεσιμότητα κρατήσεων.</li><li>Αποθηκεύστε το επιλεγμένο σχέδιο. Χρησιμοποιήστε <strong>Prepare Website Update</strong> μόνο εφόσον είναι διαθέσιμο και εξουσιοδοτημένο. Η προετοιμασία δημιουργεί ιδιωτικά το υποψήφιο αποτέλεσμα, καταγράφει το ακριβές αποτύπωμα, τις προειδοποιήσεις απόδοσης και τις αλλαγές αρχείων και δημιουργεί επαληθευμένα στιγμιότυπα πριν και μετά. Δεν αλλάζει δημόσια αρχεία.</li><li>Ελέγξτε οπτικά το αποτέλεσμα και τις προειδοποιήσεις. Ο στατικός renderer υποστηρίζει περιορισμένο σύνολο ενοτήτων και αρχείων· ορισμένες λεπτομέρειες μπορεί να παραλείπονται ή να απορρίπτονται. Ελέγξτε πλοήγηση και διατάξεις πριν ζητήσετε έγκριση.</li></ol><h3 id="ενημερωση-η-επαναφορα" tabindex="-1">Ενημέρωση ή επαναφορά <a class="header-anchor" href="#ενημερωση-η-επαναφορα" aria-label="Permalink to &quot;Ενημέρωση ή επαναφορά&quot;">​</a></h3><ol start="4"><li>Ο ιδιοκτήτης ελέγχει ανεξάρτητα την ακριβή αναθεώρηση και εγκρίνει τη συγκεκριμένη ενέργεια. Επιβεβαιώστε μόνο την ελεγμένη ενέργεια. Ενημέρωση και επαναφορά απαιτούν χωριστές εγκρίσεις μίας χρήσης. Η επαναφορά δεν είναι αυτόματη συνέπεια επεξεργασίας προσχεδίου.</li><li>Μετά από εξουσιοδοτημένη ενέργεια, επιβεβαιώστε το προβλεπόμενο περιεχόμενο και αξιόπιστο HTTPS. Αν το αποτέλεσμα είναι άγνωστο, μην επαναλάβετε την ενέργεια ή την έγκριση. Ζητήστε έλεγχο αποτυπωμάτων αναθεωρήσεων, αρχείων συναλλαγής και στιγμιοτύπων ανάκτησης πριν από νέα ενέργεια.</li></ol><p>Η έκδοση δεν αποδεικνύει απεριόριστη δημοσίευση παραγωγής, αλλαγές DNS/SSL, μεταβολές βάσης, ενεργοποίηση πραγματικών κρατήσεων ή πληρωμών. Αν λείπει ή είναι κλειδωμένο ένα εργαλείο, διατηρήστε το εξαγόμενο σχέδιο και συμβουλευτείτε τον εξουσιοδοτημένο διαχειριστή. Δείτε τις <a href="/el/release-notes/">σημειώσεις εκδόσεων</a>.</p>',17)])])}const b=e(r,[["render",i]]);export{u as __pageData,b as default};
